import { Components, Theme } from "@mui/material/styles";

const components: Components<Omit<Theme, "components">> = {
  MuiCssBaseline: {
    styleOverrides: {
      body: {
        backgroundColor: "#F5F7FB",
        color: "#1F2937",
        WebkitFontSmoothing: "antialiased",
        MozOsxFontSmoothing: "grayscale",
      },
      "*": {
        boxSizing: "border-box",
      },
      "#root": {
        minHeight: "100vh",
      },
    },
  },

  MuiPaper: {
    styleOverrides: {
      root: {
        borderRadius: 20,
        backgroundImage: "none",
      },
    },
  },

  MuiCard: {
    defaultProps: {
      elevation: 0,
    },
    styleOverrides: {
      root: {
        borderRadius: 20,
        border: "1px solid #E5E7EB",
        boxShadow: "0 6px 20px rgba(15,23,42,0.05)",
        overflow: "hidden",
      },
    },
  },

  MuiButton: {
    defaultProps: {
      disableElevation: true,
    },
    styleOverrides: {
      root: {
        borderRadius: 12,
        padding: "10px 20px",
        fontWeight: 600,
        minHeight: 44,
      },

      contained: {
        boxShadow: "none",

        "&:hover": {
          boxShadow: "0 6px 16px rgba(0,0,0,0.12)",
        },
      },

      outlined: {
        borderWidth: 1.5,

        "&:hover": {
          borderWidth: 1.5,
        },
      },
    },
  },

  MuiOutlinedInput: {
    styleOverrides: {
      root: {
        borderRadius: 12,

        "& fieldset": {
          borderColor: "#D1D5DB",
        },

        "&:hover fieldset": {
          borderColor: "#9CA3AF",
        },

        "&.Mui-focused fieldset": {
          borderWidth: 2,
        },
      },
    },
  },

  MuiTextField: {
    defaultProps: {
      size: "small",
      variant: "outlined",
      fullWidth: true,
    },
  },

  MuiTableContainer: {
    styleOverrides: {
      root: {
        borderRadius: 16,
      },
    },
  },

  MuiTableHead: {
    styleOverrides: {
      root: {
        backgroundColor: "#F9FAFB",
      },
    },
  },

  MuiTableCell: {
    styleOverrides: {
      head: {
        fontWeight: 700,
        color: "#374151",
        borderBottom: "1px solid #E5E7EB",
      },

      root: {
        paddingTop: 16,
        paddingBottom: 16,
        borderBottom: "1px solid #F1F5F9",
      },
    },
  },

  MuiChip: {
    styleOverrides: {
      root: {
        borderRadius: 8,
        fontWeight: 600,
      },
    },
  },

  MuiAvatar: {
    styleOverrides: {
      root: {
        fontWeight: 600,
      },
    },
  },

  MuiDivider: {
    styleOverrides: {
      root: {
        borderColor: "#E5E7EB",
      },
    },
  },

  MuiTooltip: {
    styleOverrides: {
      tooltip: {
        borderRadius: 8,
        fontSize: "0.8rem",
      },
    },
  },

  MuiDialog: {
    styleOverrides: {
      paper: {
        borderRadius: 20,
      },
    },
  },

  MuiDrawer: {
    styleOverrides: {
      paper: {
        border: "none",
      },
    },
  },

  MuiListItemButton: {
    styleOverrides: {
      root: {
        borderRadius: 12,

        "&.Mui-selected": {
          backgroundColor: "#E8F1FD",

          "&:hover": {
            backgroundColor: "#E8F1FD",
          },
        },
      },
    },
  },
};

export default components;
